 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0] * w for _ in range(h)]

    # Preserve each 2x2 color-2 block and rotate its four corner markers
    # clockwise onto outward diagonal rays.
    blocks = []
    for r in range(h - 1):
        for c in range(w - 1):
            if all(grid[rr][cc] == 2 for rr in (r, r + 1) for cc in (c, c + 1)):
                blocks.append((r, c))
                for rr in (r, r + 1):
                    for cc in (c, c + 1):
                        out[rr][cc] = 2

    for r, c in blocks:
        # Source corner -> destination ray corner, clockwise.
        sources = {
            'NW': (r - 1, c - 1),
            'NE': (r - 1, c + 2),
            'SE': (r + 2, c + 2),
            'SW': (r + 2, c - 1),
        }
        destinations = {'NW': 'NE', 'NE': 'SE', 'SE': 'SW', 'SW': 'NW'}
        starts = {
            'NW': (r - 1, c - 1),
            'NE': (r - 1, c + 2),
            'SE': (r + 2, c + 2),
            'SW': (r + 2, c - 1),
        }
        directions = {'NW': (-1, -1), 'NE': (-1, 1), 'SE': (1, 1), 'SW': (1, -1)}
        for src, pos in sources.items():
            sr, sc = pos
            color = grid[sr][sc] if 0 <= sr < h and 0 <= sc < w else 0
            if color == 0:
                continue
            dest = destinations[src]
            rr, cc = starts[dest]
            dr, dc = directions[dest]
            while 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = color
                rr += dr
                cc += dc
    return out


